async function syncKhatianRecordsToCloud(userId, records) {
	let syncedCount = 0;
	let errors = 0;
	for (const record of records) try {
		await setDoc(doc(db, "users", userId, "records", record.recordId), {
			recordId: record.recordId,
			userId,
			districtName: record.districtName,
			upazilaName: record.upazilaName,
			unionName: record.unionName || "",
			mouzaNameEn: record.mouzaNameEn || "",
			mouzaNameBn: record.mouzaNameBn || "",
			mouzaJlNo: record.mouzaJlNo,
			surveyType: record.surveyType,
			khatianNo: record.khatianNo,
			ownerName: record.ownerName || "",
			dagNo: record.dagNo || "",
			totalLandAcres: record.totalLandAcres || "",
			sourceUrl: record.sourceUrl || "",
			syncedAt: (/* @__PURE__ */ new Date()).toISOString()
		});
		syncedCount++;
	} catch (err) {
		errors++;
		console.warn(`Failed to sync record ${record.recordId} to cloud:`, err);
	}
	return {
		syncedCount,
		errors
	};
}
async function fetchCloudKhatianRecords(userId) {
	try {
		const snap = await getDocs(query(collection(db, "users", userId, "records"), limit(200)));
		const results = [];
		snap.forEach((docSnap) => {
			const d = docSnap.data();
			results.push({
				recordId: d.recordId || docSnap.id,
				districtName: d.districtName || "",
				upazilaName: d.upazilaName || "",
				unionName: d.unionName || "",
				mouzaNameEn: d.mouzaNameEn || "",
				mouzaNameBn: d.mouzaNameBn || "",
				mouzaJlNo: d.mouzaJlNo || "",
				surveyType: d.surveyType || "RS",
				khatianNo: d.khatianNo || "",
				ownerName: d.ownerName || "",
				dagNo: d.dagNo || "",
				totalLandAcres: d.totalLandAcres || "",
				sourceUrl: d.sourceUrl || "",
				extractedAt: d.syncedAt || (/* @__PURE__ */ new Date()).toISOString()
			});
		});
		return results;
	} catch (err) {
		handleFirestoreError(err, "list", `users/${userId}/records`);
	}
}
async function recordDriveArchiveToFirestore(userId, archive) {
	try {
		await setDoc(doc(db, "users", userId, "archives", archive.archiveId), {
			...archive,
			userId,
			uploadedAt: (/* @__PURE__ */ new Date()).toISOString()
		});
	} catch (err) {
		console.warn("Failed to record drive archive in Firestore:", err);
	}
}
