function toTitleCase(raw) {
	return raw.trim().toLowerCase().replace(/\b[a-z]/g, (c) => c.toUpperCase());
}
function createDistrictWithUpazilas(id, code, nameEn, nameBn, upazilaNames) {
	const distSlug = nameEn.toLowerCase().replace(/[^a-z0-9]+/g, "-");
	const paddedCode = String(code).padStart(2, "0");
	const jsonMatches = bangladeshUpazilasData_default.filter((u) => String(u.DISTRICT_BBS_CODE).padStart(2, "0") === paddedCode);
	let upazilas;
	if (jsonMatches.length > 0) {
		const seenSlugs = /* @__PURE__ */ new Set();
		upazilas = [];
		for (const u of jsonMatches) {
			const formattedEn = toTitleCase(u.NAME_EN);
			const upzSlug = formattedEn.toLowerCase().replace(/[^a-z0-9]+/g, "-");
			const uniqueId = seenSlugs.has(upzSlug) ? `upz-${upzSlug}-${u.BBS_CODE}` : `upz-${upzSlug}`;
			seenSlugs.add(upzSlug);
			upazilas.push({
				id: uniqueId,
				nameEn: formattedEn,
				nameBn: String(u.NAME).trim(),
				eporchaSlug: upzSlug,
				mouzas: []
			});
		}
	} else upazilas = upazilaNames.map((u) => {
		const upzSlug = u.nameEn.toLowerCase().replace(/[^a-z0-9]+/g, "-");
		return {
			id: `upz-${upzSlug}`,
			nameEn: u.nameEn,
			nameBn: u.nameBn,
			eporchaSlug: upzSlug,
			mouzas: []
		};
	});
	return {
		id,
		code,
		nameEn,
		nameBn,
		eporchaSlug: distSlug,
		upazilas
	};
}
