/**
* Normalized Geographic Database Service.
* Implements Phase 6 requirements: Stable official identifiers, unique constraints,
* data provenance, and quality logging.
*/
var GeographicDbService = class {
	constructor() {
		this.db = getFirestore();
	}
	async saveDivision(div, source = "eporcha.tech") {
		await setDoc(doc(this.db, "divisions", div.id), {
			...div,
			source,
			lastVerifiedAt: Timestamp.now(),
			status: "VERIFIED"
		}, { merge: true });
	}
	async saveDistrict(dist, divisionId, source = "eporcha.tech") {
		await setDoc(doc(this.db, "districts", dist.id), {
			...dist,
			divisionId,
			source,
			lastVerifiedAt: Timestamp.now(),
			status: "VERIFIED"
		}, { merge: true });
	}
	async saveUpazila(upz, districtId, source = "eporcha.tech") {
		await setDoc(doc(this.db, "upazilas", upz.id), {
			...upz,
			districtId,
			source,
			lastVerifiedAt: Timestamp.now(),
			status: "VERIFIED"
		}, { merge: true });
	}
	async saveMouzas(mouzas, upazilaId, source = "eporcha.tech") {
		const batch = mouzas.map((m) => {
			return setDoc(doc(this.db, "mouzas", m.id), {
				...m,
				upazilaId,
				source,
				lastVerifiedAt: Timestamp.now(),
				status: "VERIFIED",
				isValid: true
			}, { merge: true });
		});
		await Promise.all(batch);
	}
	async getDistricts(divisionId) {
		return (await getDocs(query(collection(this.db, "districts"), where("divisionId", "==", divisionId)))).docs.map((d) => d.data());
	}
	async getUpazilas(districtId) {
		return (await getDocs(query(collection(this.db, "upazilas"), where("districtId", "==", districtId)))).docs.map((d) => d.data());
	}
	async getMouzas(upazilaId) {
		return (await getDocs(query(collection(this.db, "mouzas"), where("upazilaId", "==", upazilaId), where("isValid", "==", true)))).docs.map((d) => d.data());
	}
	async logRejection(record, reason, source) {
		await setDoc(doc(collection(this.db, "geographic_data_quality_logs")), {
			originalRecord: record,
			reason,
			source,
			rejectedAt: Timestamp.now()
		});
	}
};
